// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref) public {
        // Seed the market and get free kilos
        vm.assume(caller != address(0) && caller != address(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26));
        c.seedMarket(100);
        vm.prank(caller);
        c.getFreeKilo();
        // Now call DrugDealer() (only CEO can call, but we can prank as CEO)
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();
        // Assert that lastCollect for caller is > 0
        assertTrue(c.lastCollect(caller) > 0, "lastCollect should be non-zero after DrugDealer()");
    }
}

